@pytest.mark.parametrize("case", CASES, ids=[c["name"] for c in CASES])
def test_qz_full(case):
    """全字段断言：四柱/十神/藏干/藏干十神/纳音/空亡/星运/自坐/大运5/起运/胎元/命宫/身宫(含纳音)。"""
    y, m, d = (int(x) for x in case["date"].split("-"))
    h, mi = (int(x) for x in case["time"].split(":"))
    # 校准口径：city 传空（排盘核心逻辑对比，问真 API 不接收城市）
    r = ENGINE.calculate(y, m, d, h, mi, "", case["gender"])
    ex = case["expect"]
    day_gan = r.bazi[2][0]
    assert r.bazi == ex["sizhu"], f"四柱 {r.bazi} != {ex['sizhu']}"
    assert list(r.shishen) == ex["shishen"], f"十神 {r.shishen} != {ex['shishen']}"
    assert [BRANCH_HIDDEN.get(p[1], ['?']) for p in r.bazi] == ex["canggan"], f"藏干 {case['name']}"
    assert [compute_cg_shishen(day_gan, BRANCH_HIDDEN.get(p[1], ['?'])) for p in r.bazi] == ex["canggan_ss"], f"藏干十神 {case['name']}"
    assert list(r.nayin) == ex["nayin"], f"纳音 {r.nayin} != {ex['nayin']}"
    assert list(r.kongwang) == ex["kongwang"], f"空亡 {r.kongwang} != {ex['kongwang']}"
    assert r.kongwang_day == ex["kongwang_day"], f"日旬空亡 {r.kongwang_day} != {ex['kongwang_day']}"
    assert [get_changsheng(day_gan, p[1]) for p in r.bazi] == ex["xingyun"], f"星运 {case['name']}"
    assert [get_changsheng(p[0], p[1]) for p in r.bazi] == ex["zizuo"], f"自坐 {case['name']}"
    assert [g for _, g in r.dayun[:5]] == ex["dayun5"], f"大运前5 {[g for _, g in r.dayun[:5]]} != {ex['dayun5']}"
    assert r.dayun[0][0] == ex["qiyun_sui"], f"起运虚岁 {r.dayun[0][0]} != {ex['qiyun_sui']}"
    assert list(r.qiyun_detail) == ex["qiyun_detail"], f"起运分解 {r.qiyun_detail} != {ex['qiyun_detail']}"
    assert r.taiyuan == ex["taiyuan"], f"胎元 {r.taiyuan} != {ex['taiyuan']}"
    assert r.taiyuan_nayin == ex["taiyuan_nayin"], f"胎元纳音 {r.taiyuan_nayin} != {ex['taiyuan_nayin']}"
    assert r.minggong == ex["minggong"], f"命宫 {r.minggong} != {ex['minggong']}"
    assert r.minggong_nayin == ex["minggong_nayin"], f"命宫纳音 {r.minggong_nayin} != {ex['minggong_nayin']}"
    assert r.shenggong == ex["shenggong"], f"身宫 {r.shenggong} != {ex['shenggong']}"
    assert r.shenggong_nayin == ex["shenggong_nayin"], f"身宫纳音 {r.shenggong_nayin} != {ex['shenggong_nayin']}"
    if "shensha" in ex:
        assert list(r.shensha) == ex["shensha"], f"神煞 {r.shensha} != {ex['shensha']}"
